import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

function Mainpage() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Get user data from localStorage
    const userData = localStorage.getItem("user");
    if (!userData) {
      navigate("/");
      return;
    }

    const parsedUser = JSON.parse(userData);
    setUser(parsedUser);

    // Fetch user bookings
    const userId = parsedUser.user_id;
    if (userId) {
      axios
        .get(`http://localhost:5001/api/bookings/${userId}`)
        .then((response) => {
          setBookings(response.data.bookings || []);
        })
        .catch((error) => {
          console.log("Error fetching bookings:", error);
        })
        .finally(() => {
          setLoading(false);
        });
    } else {
      setLoading(false);
    }
  }, [navigate]);

  const logout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    navigate("/");
  };

  if (!user) {
    return <div>Loading...</div>;
  }

  return (
    <div className="mainpage-container">
      <nav className="navbar navbar-dark bg-primary">
        <div className="container-fluid">
          <span className="navbar-brand mb-0 h1">CS Room Booking System</span>
          <button className="btn btn-outline-light" onClick={logout}>
            Logout
          </button>
        </div>
      </nav>

      <div className="container mt-4">
        <div className="row">
          <div className="col-md-8">
            <div className="card mb-4">
              <div className="card-header bg-primary text-white">
                <h3>ยินดีต้อนรับ, {user.displayname_th || user.displayname_en}</h3>
              </div>
              <div className="card-body">
                <p>
                  <strong>เลขนักศึกษา:</strong> {user.studentID || user.username}
                </p>
                <p>
                  <strong>คณะ:</strong> {user.faculty_name_th || user.faculty_name_en || "-"}
                </p>
                <p>
                  <strong>สาขา:</strong> {user.branch_name_th || user.branch_name_en || "-"}
                </p>
              </div>
            </div>

            <div className="card">
              <div className="card-header bg-success text-white">
                <h4>การจองห้อง</h4>
              </div>
              <div className="card-body">
                {loading ? (
                  <p>Loading bookings...</p>
                ) : bookings && bookings.length > 0 ? (
                  <table className="table table-striped">
                    <thead>
                      <tr>
                        <th>ห้อง</th>
                        <th>วันที่</th>
                        <th>เวลา</th>
                        <th>วัตถุประสงค์</th>
                      </tr>
                    </thead>
                    <tbody>
                      {bookings.map((booking) => (
                        <tr key={booking.id}>
                          <td>{booking.room}</td>
                          <td>{booking.date}</td>
                          <td>
                            {booking.start_time} - {booking.end_time}
                          </td>
                          <td>{booking.purpose || "-"}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (
                  <p>ไม่มีการจองห้อง</p>
                )}
              </div>
            </div>
          </div>

          <div className="col-md-4">
            <div className="card">
              <div className="card-header bg-info text-white">
                <h4>การจองห้องใหม่</h4>
              </div>
              <div className="card-body">
                <button className="btn btn-primary w-100">
                  จองห้อง
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Mainpage;
